diff --git a/CLAUDE.md b/CLAUDE.md
index 6d36c37..245a59c 100644
--- a/CLAUDE.md
+++ b/CLAUDE.md
@@ -26,11 +26,9 @@
 - `src/server.ts`: routes and one shared SQLite `Database`. Routes: `/` (SVG map), `/health`, `/gbfs/v3/vehicle_status.json`, `/gbfs/v3/station_status.json`, `POST /wrench`, `/crew/queue?depot=...`.
 - `src/database.ts`: schema (`stations`, `bikes`, `wrenches`, `repair_jobs`). Seeds from `data/stations.csv`, `bikes.csv`, `open-jobs.csv` when `spoke.db` is missing; open jobs become timestamps relative to now and their bikes get `is_disabled = 1`.
 - `src/feed.ts`: both GBFS responses (`ttl` 60s for SLA-12). Disabled/available counts come from `bikes.is_disabled`. `src/map-page.ts` reuses `stationStatus`, so feed changes show on the map.
-- `src/wrenches.ts`: inserts a `wrenches` row and a `repair_jobs` row (`source='wrench'`), then logs.
-- `src/crew-queue.ts`: open jobs, oldest first, each with a contract `deadline` (48h wrench, 96h crew-found).
+- `src/wrenches.ts`: in one transaction, inserts a `wrenches` row, a `repair_jobs` row (`source='wrench'`, id `J-W-<wrench id>`) and sets `bikes.is_disabled = 1`; logs after the commit. Unknown bikes get 404 before any write.
+- `src/crew-queue.ts`: open jobs, each with a contract `deadline` from `reported_at` (SLA-4: 48h wrench, 96h crew-found), sorted by deadline, then `reported_at`, then `job_id`.

 ## Things Claude gets wrong

-- **The 48 hour clock starts at the wrench, not when the job is opened.** SLA-4 counts from the rider's report (`reported_at`). `crewQueue` currently uses `opened_at` for deadlines and sort order. Don't copy that pattern.
-- **A wrench must disable the bike.** `recordWrench` doesn't set `bikes.is_disabled`, so a wrenched bike still looks rentable in the feed (SLA-12). No test covers this yet.
 - Check `data/contract/sla.yaml` before changing anything that touches wrenches, the feed, or the queue.
diff --git a/src/crew-queue.ts b/src/crew-queue.ts
index 2c66750..141a833 100644
--- a/src/crew-queue.ts
+++ b/src/crew-queue.ts
@@ -13,19 +13,24 @@ type JobRow = {
   opened_at: string;
 };

-// The contract limit: 48 hours for a wrench, 96 hours for a defect a crew found itself.
-// The clock runs from when the dispatch desk opened the job.
+// SLA-4: 48 hours for a wrench, 96 hours for a defect a crew found itself.
+// The clock runs from the report (reported_at), not from when the job was opened.
 function contractDeadline(job: JobRow): string {
   const limitHours = job.source === "wrench" ? 48 : 96;
-  return new Date(Date.parse(job.opened_at) + limitHours * HOUR).toISOString();
+  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
 }

 export function crewQueue(database: Database, depot: string | null) {
   const jobs = database
     .query("SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)")
     .all(depot) as JobRow[];
-  // Oldest job first, the way the dispatch desk has always worked.
-  jobs.sort((first, second) => first.opened_at.localeCompare(second.opened_at));
   const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
+  // The job due first goes on top. Ties: earlier report first, then job id.
+  queue.sort(
+    (first, second) =>
+      first.deadline.localeCompare(second.deadline) ||
+      first.reported_at.localeCompare(second.reported_at) ||
+      first.job_id.localeCompare(second.job_id),
+  );
   return { depot: depot ?? "all", jobs: queue };
 }
diff --git a/src/map-page.ts b/src/map-page.ts
index 53db411..716243d 100644
--- a/src/map-page.ts
+++ b/src/map-page.ts
@@ -12,10 +12,16 @@ const DISTRICT_COLOURS: Record<string, string> = {
   West: "#22c55e",
 };

-function stationDot(station: StationRow, brokenBikes: number): string {
+type StationCounts = { num_vehicles_available: number; num_vehicles_disabled: number };
+
+// The counts come only from stationStatus, so the map always matches the feed.
+function stationDot(station: StationRow, counts: StationCounts | undefined): string {
+  const available = counts?.num_vehicles_available ?? 0;
+  const brokenBikes = counts?.num_vehicles_disabled ?? 0;
   const colour = DISTRICT_COLOURS[station.district] ?? "#888";
   const dot = `<circle cx="${station.x}" cy="${station.y}" r="9" fill="${colour}">`;
-  const title = `<title>${station.station_id} ${station.name}</title></circle>`;
+  const label = `${station.station_id} ${station.name}: ${available} available, ${brokenBikes} disabled`;
+  const title = `<title>${label}</title></circle>`;
   if (brokenBikes === 0) return dot + title;
   const badge = `<circle cx="${station.x + 9}" cy="${station.y - 9}" r="8" fill="#dc2626"/>`;
   const count = `<text x="${station.x + 9}" y="${station.y - 5}">${brokenBikes}</text>`;
@@ -40,10 +46,8 @@ const STYLE = `body{font-family:system-ui,sans-serif;margin:24px;background:#f8f
 export function mapPage(database: Database): string {
   const stations = database.query("SELECT * FROM stations").all() as StationRow[];
   const feed = stationStatus(database).data.stations;
-  const brokenAt = new Map(feed.map((entry) => [entry.station_id, entry.num_vehicles_disabled]));
-  const dots = stations.map((station) =>
-    stationDot(station, brokenAt.get(station.station_id) ?? 0),
-  );
+  const countsAt = new Map(feed.map((entry) => [entry.station_id, entry]));
+  const dots = stations.map((station) => stationDot(station, countsAt.get(station.station_id)));
   const totalBroken = feed.reduce((sum, entry) => sum + entry.num_vehicles_disabled, 0);
   const totalAvailable = feed.reduce((sum, entry) => sum + entry.num_vehicles_available, 0);
   return `<!doctype html><html><head><meta charset="utf-8"><title>Kestrel Bike Share</title>
diff --git a/src/wrenches.ts b/src/wrenches.ts
index 8eba170..8c443d4 100644
--- a/src/wrenches.ts
+++ b/src/wrenches.ts
@@ -1,4 +1,5 @@
 // POST /wrench: a rider pressed the wrench button in the app to report a broken bike.
+// SLA-12: the bike leaves service at once, so the feed never shows a reported bike as rentable.
 import type { Database } from "bun:sqlite";
 import { logEvent } from "./log";

@@ -7,23 +8,29 @@ type BikeRow = { bike_id: string; station_id: string };
 type StationRow = { depot: string };

 export function recordWrench(database: Database, report: WrenchReport) {
+  // Unknown bikes are turned away before any write.
   const bike = database.query("SELECT * FROM bikes WHERE bike_id = ?").get(report.bike_id ?? "");
   if (!bike) return { status: 404, body: { error: `no bike called ${report.bike_id}` } };
   const { bike_id, station_id } = bike as BikeRow;
   const station = database.query("SELECT depot FROM stations WHERE station_id = ?").get(station_id);
+  const depot = (station as StationRow).depot;
   const reportedAt = new Date().toISOString();
   const fault = report.fault ?? "OTHER";

-  database
-    .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
-    .run(bike_id, station_id, fault, reportedAt);
-
-  // A dispatcher opens the repair job from the wrench.
-  const jobId = `J-${Date.now()}`;
-  const depot = (station as StationRow).depot;
-  database
-    .query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, 'wrench', ?, ?, ?, NULL)")
-    .run(jobId, bike_id, station_id, depot, fault, reportedAt, reportedAt);
+  // The wrench, its repair job and the disabled flag are kept together or not at all.
+  const record = database.transaction(() => {
+    const wrench = database
+      .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
+      .run(bike_id, station_id, fault, reportedAt);
+    // The wrench row id makes the job id unique, even for two wrenches in the same millisecond.
+    const jobId = `J-W-${wrench.lastInsertRowid}`;
+    database
+      .query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, 'wrench', ?, ?, ?, NULL)")
+      .run(jobId, bike_id, station_id, depot, fault, reportedAt, reportedAt);
+    database.query("UPDATE bikes SET is_disabled = 1 WHERE bike_id = ?").run(bike_id);
+    return jobId;
+  });
+  const jobId = record();

   logEvent("wrench", { bike_id, station_id, fault, job_id: jobId });
   return { status: 201, body: { job_id: jobId, bike_id } };

